void sc_hex_dump(const u8 * in, size_t count, char *buf, size_t len)
{
        char *p = buf;
        int lines = 0;

        if (buf == NULL || (in == NULL && count != 0)) {
                return;
        }
        buf[0] = 0;
        if ((count * 5) > len)
                return;
        while (count) {
                char ascbuf[17];
                size_t i;

                for (i = 0; i < count && i < 16; i++) {
                        sprintf(p, "%02X ", *in);
                        if (isprint(*in))
                                ascbuf[i] = *in;
                        else
                                ascbuf[i] = '.';
                        p += 3;
                        in++;
                }
                count -= i;
                ascbuf[i] = 0;
                for (; i < 16 && lines; i++) {
                        strcat(p, "   ");
                        p += 3;
                }
                strcat(p, ascbuf);
                p += strlen(p);
                sprintf(p, "\n");
                p++;
                lines++;
        }
}
